// Which drawing a weapon gets, by its table and type.
function weaponIcon(o) {
  const t = (o && o.type) || "";
  if (!o) return "item";
  if (VICON["w:" + o.n]) return "w:" + o.n; // 13 Nov: the weapon's own traced icon, when it has one
  if (o.tab === "MW") return t === "Hand" ? "fist" : t[0] === "B" ? "blunt" : t[0] === "S" ? "blade" : "spear";
  if (o.tab === "EX") return t === "Grenade" ? "grenade" : t === "Launcher" ? "launcher" : t === "Missile" ? "missile" : "mine";
  if (o.tab === "EW") {
    if (/Laser/.test(t)) return "laser";
    if (/Plasma/.test(t)) return "plasma";
    // 13 Nov, the user's subtypes: elemental weapons by what they fire, everything Powered or Magnetic as the rail gun
    if (o.ammo === "Flamer Fuel") return "fire";
    if (o.ammo === "Nitrogen Tank") return "cold";
    if (t === "Electric") return "shock";
    if (t === "Powered" || t === "Magnetic") return "rail";
    if (o.ammo === "Acid") return "skull"; // the Acid Soaker: the acid skull (the user's pick)
    return "zap";
  }
  if (/Shotgun/.test(t)) return "shotgun";
  if (/bow/i.test(t)) return "bow";
  if (/Revolver/.test(t)) return "revolver";
  if (/Pistol|Special/.test(t)) return "pistol";
  if (/SMG|PDW/.test(t)) return "smg";
  if (/Sniper|DMR|Anti-Mat/.test(t)) return "sniper";
  if (/LMG|Heavy/.test(t)) return "heavy";
  return "rifle";
}
