    `<svg x="0" y="0" width="24" height="24" viewBox="${vb}"><g class="t"></g><path class="f" fill-rule="evenodd" d="${d}"/></svg>`;
// 13 Nov: a second tone. Each icon's main closed shape (unless it says otherwise with a "t" part of its own) gets a soft tinted copy
// underneath, so the drawings have body, not just outlines. CSS: .vic .t / .hzi .t.
for (const k of Object.keys(VICON)) {
  const s = VICON[k];
  if (s.includes('class="t"')) continue;
  const m = s.match(/<(rect|circle|ellipse)\b(?![^>]*class=)[^>]*\/>|<path\b(?![^>]*class=)[^>]*\bd="[^"]*[zZ]"[^>]*\/>/);
  if (m) VICON[k] = m[0].replace(/^<(\w+)/, '<$1 class="t"') + s;
}
const vicon = (name, cls = "") => `<svg class="vic ${cls}" viewBox="0 0 24 24" aria-hidden="true">${VICON[name] || VICON.item}</svg>`;
